/* Eight bounded poses animate painted body parts; simulation coordinates never change. */
MW.actorPose=game=>{if(game.slash>0){const duration=game.slashSkill?.45:.22;return{kind:game.slashSkill?'skill':'attack',phase:Math.min(7,Math.floor((1-game.slash/duration)*8)),job:game.p.job};}return{kind:game.moving?'walk':'idle',phase:game.moving?Math.floor(game.time*12)%8:0,job:game.p.job};};
MW.poseValues=pose=>{const phase=(pose?.phase||0)/8*Math.PI*2,t=(pose?.phase||0)/7,walk=pose?.kind==='walk',attack=pose?.kind==='attack',skill=pose?.kind==='skill';return{step:walk?Math.sin(phase):0,arm:walk?Math.sin(phase)*.16:attack?(pose?.job==='archer'?-.3-Math.sin(t*Math.PI)*.45:pose?.job==='mage'?-.25+Math.sin(t*Math.PI)*.6:-.9+Math.sin(t*Math.PI)*1.9):skill?-.65-Math.sin(t*Math.PI)*.5:0,lean:attack?Math.sin(t*Math.PI)*.055:skill?-.025:0,weapon:attack?(pose?.job==='archer'?Math.sin(t*Math.PI)*.12:pose?.job==='mage'?-.45+Math.sin(t*Math.PI)*.7:-1.3+Math.sin(t*Math.PI)*2.5):skill?-.65+Math.sin(t*Math.PI)*.4:walk?Math.sin(phase)*.09:0};};
(()=>{const R=MW.Renderer.prototype;
R.rigBody=function(c,sprite,face,pose){if(!pose||pose.kind==='idle'){c.drawImage(sprite,0,0,80,90);return;}const v=MW.poseValues(pose),sx=sprite.width/80,sy=sprite.height/90,part=(x,y,w,h,px,py,angle=0,dx=0,dy=0)=>{c.save();c.translate(px+dx,py+dy);c.rotate(angle);c.drawImage(sprite,x*sx,y*sy,w*sx,h*sy,x-px,y-py,w,h);c.restore();};part(0,0,80,34,40,34,v.lean);part(28,34,24,38,40,66,v.lean);part(0,34,28,38,27,38,face===3?-v.arm:v.arm);part(52,34,28,38,53,38,face===3?v.arm:-v.arm);part(0,72,40,18,34,74,0,v.step*1.5,-Math.max(0,v.step)*2.8);part(40,72,40,18,46,74,0,-v.step*1.5,-Math.max(0,-v.step)*2.8);};
R.animatedMonster=function(e,game){const sprite=this.monster(e.type,this.world.region,e.boss),w=sprite.logicalWidth,h=sprite.logicalHeight,c=this.ctx,attack=Math.max(0,e.attackAnim||0),windup=e.cast>0,phase=attack?1-attack/.36:0,amount=attack?Math.sin(Math.max(0,phase)*Math.PI):0,angle=e.attackFace??Math.atan2(game.p.y-e.y,game.p.x-e.x),stride=e.moving?Math.sin(game.time*12+e.seed)*.025:0;c.save();c.imageSmoothingEnabled=true;c.translate(e.x,e.y);c.rotate((windup?Math.sin(game.time*18)*.025:stride)+Math.cos(angle)*amount*.11);c.scale(1+(windup?.035:amount*.1),1-(windup?.03:amount*.035));if(e.type===2&&(attack||e.moving)){c.save();c.translate(-w/2+Math.cos(angle)*amount*8,-h+Math.sin(angle)*amount*5);c.scale(w/80,h/90);this.rigBody(c,sprite,0,{kind:attack?'attack':'walk',phase:attack?Math.min(7,Math.floor(phase*8)):Math.floor(game.time*12)%8});c.restore();}else c.drawImage(sprite,-w/2+Math.cos(angle)*amount*8,-h+Math.sin(angle)*amount*5,w,h);if(attack){c.strokeStyle=e.type===1?'#c3a2f3':'#ffcbad';c.lineWidth=e.boss?3:1.7;c.globalAlpha=amount;c.beginPath();c.arc(Math.cos(angle)*w*.35,Math.sin(angle)*h*.15-22,w*.4,angle-.7,angle+.7);c.stroke();}if(windup){c.globalAlpha=.6;c.fillStyle='#debaf8';for(let i=0;i<4;i++){c.beginPath();c.arc(Math.sin(game.time*5+i)*w*.35,-h*.5-i*6,1.5,0,7);c.fill();}}c.restore();};
})();
